data.transform:
(
  /* CONSTANTS */
  $SERIAL_NO := serialNo;
  $INCOMING_ACTION := action;
  $SUPPLIER_SHIPMENT_ID := supplierShipmentId;
  $TRANSFER_SHIPMENT_ID := transferShipmentId;
  $SUPPLIER_SHIMPENT_ID := supplierShipmentId;
  $STATUSES := {
    "STAGE": "Staged",
    "STAGING": "Staging",
    "LOAD": "Loaded",
    "LOADING": "Loading"
  };

  /* QUERIES */

  $GET_ALL_LOAD_LINE_INVENTORY := "
    query GET_ALL_LOAD_LINE_INVENTORY($id: String!) {
      load(where: { id: {_eq:$id}}) {
    		edges{
          node{
        		id    
            supplierShipments {
              edges {
                node {
                  lines: supplierShipmentLines {
                    edges {
                      node {
                        inventory: supplierShipmentLineInventories {
                          edges {
                            node {
                              id
                              shipmentLineInventoryStatusId
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
            transferShipments {
              edges {
                node {
                  lines: transferShipmentLines {
                    edges {
                      node {
                        inventory: transferShipmentLineInventories {
                          edges {
                            node {
                              id
                              shipmentLineInventoryStatusId
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
            customerShipments {
          edges {
            node {
              lines: customerShipmentLines {
                edges {
                  node {
                    inventory: customerShipmentLineInventories {
                      edges {
                        node {
                          id
                          shipmentLineInventoryStatusId
                        }
                      }
                    }
                  }
                }
              }
            }
          }
        }
          }
        }
      }
    }
  ";


  /* PREPARE OUTPUT */
  $isTransferShipment := $isUndefined($SUPPLIER_SHIPMENT_ID);

  $SHIPMENT := $isTransferShipment ?
    {
      "id": $TRANSFER_SHIPMENT_ID,
      "_shipmentType": "transferShipment"
    } :
    {
       "id": $SUPPLIER_SHIMPENT_ID,
       "_shipmentType": "supplierShipment"
    };


  /* OUTPUT */
  {
      "flowStartedAt": $now(),
      "SHIPMENT": $SHIPMENT,
      "SERIAL_NO": $SERIAL_NO,
      "INVENTORY_STATUS": $lookup($STATUSES, $INCOMING_ACTION),
      "CONSTANTS": {
        "NON_UPDATABLE_STATUSES": ["Shipped"],
        "STATUSES": $STATUSES,
        "INCOMING_ACTION": $INCOMING_ACTION
      },
      "QUERIES": {
        "GET_ALL_LOAD_LINE_INVENTORY": $GET_ALL_LOAD_LINE_INVENTORY
      },
      "MUTATIONS": {
      }
    }
)

(
  /* CONSTANTS */
  $SHIPMENT := $state.context.SHIPMENT;

  /* PREPARE OUTPUT */
  $result := $query({
    "statement": '
      query GET_SHIPMENT($id: String!){
        shipment: ' & $SHIPMENT._shipmentType & '(where: {
          id: {_eq: $id}
        }) {
          edges{
            node{
              id
              shipmentStatusId
              number
              loadId
              load {
                id
                loadStatusId
                number
              }
            }
          }

          }
      }
    ',
    "variables": {
      "id": $SHIPMENT.id
    }
  });

  /* OUTPUT */
  {
    "SHIPMENT": $merge([
        $result.shipment.edges.node,
        {
          "type": $SHIPMENT._shipmentType
        }
      ])
  }
)

(
  /* CONSTANTS */
  $CONTEXT := $state.context;
  $SHIPMENT := $CONTEXT.SHIPMENT;
  $SERIAL_NO := $CONTEXT.SERIAL_NO;


  /* PREPARE OUTPUT */
  $result := $query({
    "statement": '
      query GetShipmentLineInventory($serialNo: String!, $id: String!) {
        shipmentLineInventory: ' & $SHIPMENT._shipmentType & 'LineInventory(where: {
          _and:[
              {
                inventoryId: {
                    _eq: $serialNo
                }
              },
              {
                ' & $SHIPMENT._shipmentType & 'Line: {
                  ' & $SHIPMENT._shipmentType & 'Id: {
                    _eq: $id
                  }
                }
              }
            ]
        }) {
          edges{
            node{
              id
              shipmentLineInventoryStatusId
            }
          }
        }
      }
    ',
    "variables": {
      "serialNo": $SERIAL_NO,
      "id": $SHIPMENT.id
    }
  }).shipmentLineInventory.edges.node;

  /* OUTPUT */
  {
    "INVENTORY": $isNil($result) ? {} : $result
  };
)

(
  /* FUNCTIONS */
  $pascalCase := function ($string) { $camelCase($string) ~> $upperFirst };

  /* CONSTANTS */
  $CONTEXT := $state.context;
  $INVENTORY := $CONTEXT.INVENTORY;
  $PASCAL_CASE_SHIPMENT_TYPE := $CONTEXT.SHIPMENT._shipmentType ~> $pascalCase;
  $STATUS := $CONTEXT.INVENTORY_STATUS;

  /* PREPARE OUTPUT */
  $result := $mutate({
    "statement": '
      mutation UpdateShipmentLineInventory($id: ID!, $status: ID!){
        updatedShipment: update' & $PASCAL_CASE_SHIPMENT_TYPE & 'LineInventory(payload: {
          where: {
            id: $id
          },
          update: {
            shipmentLineInventoryStatusId: $status
          }
        }) {
          id
        }
      }
    ',
    "variables": {
      "id": $INVENTORY.id,
      "status": $STATUS
    }
  }).updatedShipment[0];

  /* OUTPUT */
  {
    "updatedShipmentLineInventory": $isUndefined($result) ? {} : $result
  };
)

(
  /* FUNCTIONS */
  $getAllLoadLineInventory := function($payload) {(
    $flatten([
      $payload.load.edges.node.transferShipments.edges.node.lines.edges.node.inventory.edges.node,
      $payload.load.edges.node.supplierShipments.edges.node.lines.edges.node.inventory.edges.node,
      $payload.load.edges.node.customerShipments.edges.node.lines.edges.node.inventory.edges.node
    ]);
  )};

  $createShipmentLineInventoryQuery := function($shipmentType) {(
      '
        query GET_ALL_SHIPMENT_LINE_INVENTORY($id: String!) {
          shipmentConnection: ' & $shipmentType & '(where: {
            id: {
              _eq: $id
            }
          }) {
              edges {
                node {
                 lines: ' & $shipmentType & 'Lines {
                    edges {
                      node {
                       inventory: ' & $shipmentType & 'LineInventories {
                          edges {
                            node {
                              id
                              shipmentLineInventoryStatusId
                            }
                          }
                        }
                      }
                    }
                  }
                }
              }
            }
        }
      ';
  )};

  /* CONSTANTS */
  $CONTEXT := $state.context;
  $SHIPMENT := $CONTEXT.SHIPMENT;
  $GET_ALL_LOAD_LINE_INVENTORY := $CONTEXT.QUERIES.GET_ALL_LOAD_LINE_INVENTORY;
  $hasLoad := $not($isNil($SHIPMENT.loadId));
  $QUERY_PAYLOAD := $hasLoad ?
    {
      "statement": $GET_ALL_LOAD_LINE_INVENTORY,
      "variables": {
        "id": $SHIPMENT.loadId
      }
    } :
    {
      "statement": $createShipmentLineInventoryQuery($SHIPMENT._shipmentType),
      "variables": {
        "id": $SHIPMENT.id
      }
    };

  /* PREPARE OUTPUT */
  $result := $query($QUERY_PAYLOAD);
  $allInventory := $hasLoad ?
      $getAllLoadLineInventory($result) :
      $result.shipmentConnection.edges[0].node.lines.edges.node.inventory.edges.node;
  $shipmentInventory := $hasLoad ?
    $lookup($result.load.edges.node, $SHIPMENT._shipmentType & 's').edges[0].node.lines.edges.node.inventory.edges.node :
    $allInventory;

   /*OUTPUT  */
  {
    "allShipmentLineInventory": $allInventory,
    "shipmentLineInventory": $shipmentInventory
  };
)

(
  /* CONSTANTS */
  $CONTEXT := $state.context;
  $SHIPMENT := $CONTEXT.SHIPMENT;
  $SHIPMENT_LINE_INVENTORY := $CONTEXT.shipmentLineInventory;
  $INVENTORY_STATUS := $CONTEXT.INVENTORY_STATUS;
  $STATUSES := $CONTEXT.CONSTANTS.STATUSES;
  $SHIPMENT := $CONTEXT.SHIPMENT;
  $SERIAL_NO := $CONTEXT.SERIAL_NO;
  /*   {
    "STAGE": "Staged",
    "STAGING": "Staging",
    "LOAD": "Loaded",
    "LOADING": "Loading"
  } */

  /* FUNCTIONS */
  $pascalCase := function ($string) { $camelCase($string) ~> $upperFirst };

  $createShipmentUpdate := function($shipmentType) {(
    $pascalCaseShipmentType := $pascalCase($shipmentType);

    '
      mutation UpdateShipmentStatus($id: ID!, $status: ID!) {
        updatedShipment: update' & $pascalCaseShipmentType & '(payload: {
          where: {
            id: $id
          },
          update: {
            shipmentStatusId: $status
          }
        }) {
          id
        }
      }
    '
  )};

  $getCompleteStatus := function($inventoryStatus) {(
    $inventoryStatus = $STATUSES.STAGE ?
      $STATUSES.STAGE : $STATUSES.LOAD
  )};

  $getPartialStatus := function($inventoryStatus) {(
    $inventoryStatus = $STATUSES.STAGE ?
      $STATUSES.STAGING : $STATUSES.LOADING
  )};


  /* PREPARE OUTPUT */
  $distinctStatuses := $distinct($SHIPMENT_LINE_INVENTORY.shipmentLineInventoryStatusId);
  $shipmentComplete := ($count($distinctStatuses) = 1) and $distinctStatuses[0] = $INVENTORY_STATUS;

  $updateStatus := $shipmentComplete ?
     $getCompleteStatus($INVENTORY_STATUS) :
     $getPartialStatus($INVENTORY_STATUS);

  $mutate({
      "statement": $createShipmentUpdate($SHIPMENT._shipmentType),
      "variables": {
        "status": $updateStatus,
        "id": $SHIPMENT.id
      }
    });

  {
    "message": "Inventory " & $SERIAL_NO & " successfully " & $lowerFirst($INVENTORY_STATUS) & " to shipment " & $SHIPMENT.number & ".",
    "severity": "success"
  };
)

(
  /* CONSTANTS */
  $CONTEXT := $state.context;
  $LOAD := $CONTEXT.SHIPMENT.load;
  $ALL_SHIPMENT_LINE_INVENTORY := $CONTEXT.allShipmentLineInventory;
  $INVENTORY_STATUS := $CONTEXT.INVENTORY_STATUS;
  $STATUSES := $CONTEXT.CONSTANTS.STATUSES;
  $SHIPMENT := $CONTEXT.SHIPMENT;
  $SERIAL_NO := $CONTEXT.SERIAL_NO;

  /*  MUTATIONS */
  $UPDATE_LOAD := '
      mutation UpdateLoadStatus($id: ID!, $status: ID!) {
        updatedLoad: updateLoad(payload: {
          where: {
            id: $id
          },
          update: {
            loadStatusId: $status
          }
        }) {
          id
        }
      }
    ';

  /* FUNCTIONS */
  $getCompleteStatus := function($inventoryStatus) {(
    $inventoryStatus = $STATUSES.STAGE ?
      $STATUSES.STAGE : $STATUSES.LOAD
  )};

  $getPartialStatus := function($inventoryStatus) {(
    $inventoryStatus = $STATUSES.STAGE ?
      $STATUSES.STAGING : $STATUSES.LOADING
  )};


  /* PREPARE OUTPUT */
  $distinctStatuses := $distinct($ALL_SHIPMENT_LINE_INVENTORY.shipmentLineInventoryStatusId);
  $loadComplete := ($count($distinctStatuses) = 1) and $distinctStatuses[0] = $INVENTORY_STATUS;

  $updateStatus := $loadComplete ?
     $STATUSES.LOAD :
     $STATUSES.LOADING;

  $mutate({
      "statement": $UPDATE_LOAD,
      "variables": {
        "status": $updateStatus,
        "id": $LOAD.id
      }
    });

  {
    "message": "Inventory " & $SERIAL_NO & " successfully " & $lowerFirst($INVENTORY_STATUS) & " to shipment " & $SHIPMENT.number & ".",
    "severity": "success"
  };
)

(
  /* CONSTANTS */
  $CONTEXT := $state.context;
  $SHIPMENT := $CONTEXT.SHIPMENT;
  $SERIAL_NO := $CONTEXT.SERIAL_NO;

  /* OUTPUT */
  {
    "message": "Inventory " & $SERIAL_NO & " is not allocated to shipment " & $SHIPMENT.number & ".",
    "severity": "warning"
  };
)

(
  /* CONSTANTS */
  $LOAD := $state.context.SHIPMENT.load;

  /* OUTPUT */
  {
    "message": "Load " & $LOAD.number & " has a status of " & $LOAD.loadStatusId & " and can no longer be updated.",
    "severity": "warning"
  };
)

(
  /* CONSTANTS */
  $SHIPMENT := $state.context.SHIPMENT;

  /* OUTPUT */
  {
    "message": "Shipment " & $SHIPMENT.number & " has a status of " & $SHIPMENT.shipmentStatusId & " and can no longer be updated.",
    "severity": "warning"
  };
)

data.query:
query Query($whereInventory: InventoryWhereInput, $orderBy: [InventoryOrderByInput!], $first: Int, $after: String, $whereShipment:ShipmentWhereInput) {
  inventory(where: $whereInventory, orderBy: $orderBy, first: $first, after: $after) {
    edges {
      node {
        id
        grossWeight 
        weightUnitId
        quantity {
          value
          unitId
        }
        productId
        inventoryStatusId
        inventoryStatus {
          id
          active
          movePrevent
          shipPrevent
          productionLoaded
          staged
          loaded
        }
        locationId
        lotId
        productStrategyProcess {
          id
          productStrategy {
            productId
          }
        }
      }
    }
},
  shipment(where: $whereShipment) {
    edges {
      node {
        id
        load {
          id
          number
          locationId
          grossWeight {
            value unitId
          }
        }
        shipmentStage {
          id
          active
          hold

        }
        shipmentLines {
          edges {
            node {
              id
              stagedQuantity{value unitId}
              loadedQuantity{value unitId}
              shipmentLineStageId
              productId

              shipmentLineInventory {
                edges {
                  node {
                    id
                    inventoryId
                    shipmentLineInventoryStatusId

                  }
                }
              }
            }
          }
        }
      }
    }
  }
}

data.variablesTransform:
(
$inventory := $state.context.LOCAL.inventory;
$shipment := $state.context.LOCAL.shipment;
$line := $shipment.shipmentLines.edges.node[productId=$inventory.productStrategyProcess.productStrategy.productId];
{
  "payloadLineInventory":[{
    "create": {
      "inventoryId": $inventory.id,
      "shipmentLineId": $line.id,
      "shipmentLineInventoryStatusId": "Loaded"
    }
  }],
  "payloadLine": [{
    "update": {
    /* Used to have staged Qty, changed to loaded QTY the Packing will changed to staged */
      "loadedQuantity": {
        "value": $coalesce([$line.loadedQuantity.value,0]) + $coalesce([$inventory.quantity.value,0]),
        "unitId": $coalesce([$inventory.quantity.unitId,$line.loadedQuantity.unitId])
      }
    },
    "where": {
      "id": $line.id
    }
  }],
  "payloadLoad":[],
  "payloadTransaction": [{
    "create": {
      "transactionTypeId": "Material Load",

      "sourceQuantity":$inventory.quantity,
      "customData": $state.claims,
      "destinationQuantity": $inventory.quantity,
      "sourceInventoryId":$inventory.id,
      "destinationInventoryId":$inventory.id,
      "sourceLocationId":$coalesce([$inventory.locationId[0], null]),
      "destinationLocationId": $coalesce([$shipment.load.locationId[0], null]),
      "sourceInventoryStatusId":$inventory.inventoryStatusId,
      "destinationInventoryStatusId":"Loaded",
      "sourceProductStrategyProcessId":$inventory.productStrategyProcess.id,
      "destinationProductStrategyProcessId":$inventory.productStrategyProcess.id,
      "sourceLotId":$inventory.lotId,
      "destinationLotId":$inventory.lotId
    }
  }],
  "payloadInventory": [{
    "update": {
      "inventoryStatusId": "Loaded",
      "locationId": $coalesce([$shipment.load.locationId[0], null])
    },
    "where": {
      "id": $inventory.id
    }
  }]
}
)

data.mutation:
mutation ShipIt($payloadLineInventory: [ShipmentLineInventoryCreatePayloadInput!]!, $payloadTransaction: [InventoryTransactionCreatePayloadInput!]!, $payloadInventory: [InventoryUpdatePayloadInput!]!) {
  createShipmentLineInventory(payload: $payloadLineInventory) {
    id
  }
  createInventoryTransaction(payload: $payloadTransaction) {
    id
  }
  updateInventory(payload: $payloadInventory) {
    id
  }
}

