data.mutation:
mutation ShipIt(
  $payloadLineInventory:[ShipmentLineInventoryUpdatePayloadInput!]!, 
  $payloadLine:[ShipmentLineUpdatePayloadInput!]!, 
  $payloadLoad:[LoadUpdatePayloadInput!]!,
  $payloadTransaction:[InventoryTransactionCreatePayloadInput!]!,
  $payloadInventory:[InventoryUpdatePayloadInput!]!,
  $payloadShipment:[ShipmentUpdatePayloadInput!]!,
  $masterPayload: [MasterInventoryUpdatePayloadInput!]!
  $salesOrderLineReleasePayload: [SalesOrderLineReleaseUpdatePayloadInput!]!
){
  updateShipmentLineInventory(payload:$payloadLineInventory){id},
  updateShipmentLine(payload:$payloadLine){id},
  updateLoad(payload:$payloadLoad){id},
  createInventoryTransaction(payload:$payloadTransaction){id}
  updateInventory(payload:$payloadInventory){id},
  updateShipment(payload:$payloadShipment){id salesOrderId}
  updateMasterInventory(payload: $masterPayload){id}
  updateSalesOrderLineRelease(payload: $salesOrderLineReleasePayload) { id }
}

