data.variablesTransform:
(
  $fulfilled := function($v){ $v = "Fulfilled"};
  $payloads := salesOrder.edges.node.(
    $linesPayload := [lines.edges.node.(
      {
        "where": { "id": id},
        "update":{ 
          "salesOrderLineStatusId": $all([salesOrderLineReleases.edges.node.salesOrderLineReleaseStatusId], $fulfilled )?
            "Fulfilled" :
            "Partially Fulfilled"
        }
      }
    )];

     $salesOrderPayload := [{
      "where": { "id": id},
      "update": { 
        "salesOrderStatusId": $all([$linesPayload.update.salesOrderLineStatusId], $fulfilled) ?
        "Fulfilled" :
        "Partially Fulfilled"
      }
    }];

    { "linesPayload": $linesPayload, "salesOrderPayload": $salesOrderPayload}

  );

  {"salesOrderLinePayload": $payloads.linesPayload, "salesOrderPayload": $payloads.salesOrderPayload}

)

